document.querySelectorAll('[data-bundle]').forEach(function(b){b.addEventListener('click',function(){document.querySelectorAll('[data-bundle]').forEach(function(x){x.setAttribute('aria-pressed',String(x===b));x.closest('.cp-bundle').classList.toggle('is-selected',x===b)});document.querySelector('.cp-bundle-status').textContent='Wybrano '+b.dataset.bundle+' — '+b.dataset.price+' zł. To wybór demonstracyjny, bez składania zamówienia.'})});
